package kr.co.donationserver.command;
import kr.co.donationserver.service.EconomyService;import net.minecraft.command.*;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.server.MinecraftServer;import java.util.*;
public class DonateCommand extends PublicPlayerCommand {public String getName(){return "기부";}public int getRequiredPermissionLevel(){return 0;}public List<String> getAliases(){return Collections.singletonList("donate");}public String getUsage(ICommandSender s){return "/기부 <금액>";}public void execute(MinecraftServer server,ICommandSender sender,String[] args)throws CommandException{EntityPlayerMP p=getCommandSenderAsPlayer(sender);if(args.length!=1)throw new WrongUsageException(getUsage(sender));long n=parseLong(args[0],1,Long.MAX_VALUE);EconomyService.donate(p,n);}}
